`timescale 1ns/1ps
module tb_v2_voice_engine;logic clk=0,rst_n=0,sc=0,ev=0;logic [95:0] data;logic er;logic signed [15:0] mix;logic sv,ov;logic [31:0] bm;logic [7:0] rc;logic [5:0] ac;integer i;always #5 clk=~clk;v2_voice_engine_mux dut(.clk,.rst_n,.sample_ce(sc),.event_valid(ev),.event_ready(er),.event_data(data),.mixed_sample(mix),.sample_valid(sv),.active_bitmap(bm),.voice_overflow(ov),.revoice_count(rc),.active_voice_count(ac));task send(input [3:0]t,input[7:0]n);begin @(negedge clk);data=0;data[94:91]=t;data[71:64]=n;data[63:56]=100;ev=1;@(posedge clk);#1;ev=0;end endtask initial begin repeat(2)@(posedge clk);rst_n=1;for(i=0;i<32;i=i+1)send(1,60+i);send(1,100);if(!ov||ac!=32)$fatal(1,"capacity");send(3,60);send(2,60);if(rc==0||bm[0])$fatal(1,"release/revoice");$display("tb_v2_voice_engine PASS");$finish;end endmodule
